  function cardRank(id){return state.cards.get(id)||0;}
  function hasCard(id){return cardRank(id)>0;}
  function formatTime(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;}
  function clamp(value,min,max){return Math.max(min,Math.min(max,value));}
  function enemyRadius(enemy){return enemy.radius||enemy.type.radius;}
  function escapeHtml(text){return String(text).replace(/[&<>'"]/g,(char)=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[char]);}
  function showToast(text){const toast=$("#statusToast");toast.textContent=text;toast.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove("show"),1900);}
  function persistSettings(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(state.settings));}catch{/* optional preference */}}
  function applySettings(){const scale=clamp(Number(state.settings.fontScale)||DEFAULT_SETTINGS.fontScale,100,160);state.settings.fontScale=scale;if(!["sequential","random"].includes(state.settings.musicMode))state.settings.musicMode="sequential";if(!["celestial","tactical"].includes(state.settings.enemyStyle))state.settings.enemyStyle="celestial";if(!CARD_PREFERENCES.some((item)=>item.id===state.settings.cardPreference))state.settings.cardPreference="";document.documentElement.style.setProperty("--ui-font-scale",String(scale/100));if($("#fontScaleInput"))$("#fontScaleInput").value=scale;if($("#fontScaleValue"))$("#fontScaleValue").textContent=`${scale}%`;if($("#pauseOnDraftInput"))$("#pauseOnDraftInput").checked=!!state.settings.pauseOnDraft;if($("#musicModeInput"))$("#musicModeInput").value=state.settings.musicMode;if($("#enemyStyleInput"))$("#enemyStyleInput").value=state.settings.enemyStyle;$$('input[name="cardPreference"]').forEach((radio)=>{radio.checked=radio.value===state.settings.cardPreference;});const preference=CARD_PREFERENCES.find((item)=>item.id===state.settings.cardPreference);if($("#preferenceStatus"))$("#preferenceStatus").textContent=preference?`偏好：${preference.name}`:"未选择";updateTrackLabel();}
  function updateFontScale(value){state.settings.fontScale=clamp(Number(value)||DEFAULT_SETTINGS.fontScale,100,160);applySettings();persistSettings();}
  function updateDraftPause(value){state.settings.pauseOnDraft=!!value;if(state.drafting){state.paused=state.settings.pauseOnDraft;syncPauseUI();}persistSettings();}
  function updateMusicMode(value){state.settings.musicMode=value==="random"?"random":"sequential";applySettings();persistSettings();showToast(state.settings.musicMode==="random"?"背景音乐：随机播放":"背景音乐：顺序循环");}
  function updateEnemyStyle(value){state.settings.enemyStyle=value==="tactical"?"tactical":"celestial";applySettings();persistSettings();showToast(state.settings.enemyStyle==="celestial"?"敌军外观：天体单位":"敌军外观：战术单位");}
  function updateCardPreference(value){const preference=CARD_PREFERENCES.find((item)=>item.id===value);if(!preference)return;state.settings.cardPreference=preference.id;applySettings();persistSettings();if(state.drafting)generateOffers();showToast(`卡牌偏好：${preference.name} · 三选一锁定 1 张`);}
  function resetSettings(){state.settings={...DEFAULT_SETTINGS};applySettings();persistSettings();showToast("设置已恢复默认");}

  function loadAccountStore(){try{const saved=JSON.parse(localStorage.getItem(ACCOUNT_KEY));if(saved&&Array.isArray(saved.accounts))return {currentId:saved.currentId||null,accounts:saved.accounts};}catch{/* clean archive */}return {currentId:null,accounts:[]};}
  function persistAccountStore(){try{localStorage.setItem(ACCOUNT_KEY,JSON.stringify(state.accountStore));}catch{showToast("本机存储空间不足");}}
  function activeAccount(){if(!state.authenticated)return null;return state.accountStore.accounts.find((account)=>account.id===state.accountStore.currentId)||null;}
  function ensureProgress(account=activeAccount()){if(!account)return {maxClearedWave:0,totalBountyRewards:0};account.progress||={maxClearedWave:Math.max(0,(account.best?.wave||1)-1),totalBountyRewards:0};return account.progress;}
