    const steal=cardRank("lifesteal");if(steal&&!options.noLifesteal){let healing=dealt*(.0025+steal*.0035);if(hasCard("blood_engine")&&state.globalBarrierHp/state.globalBarrierMax<.5)healing*=2;healCore(healing,hasCard("blood_engine")?"鲜血引擎":"吸血",hasCard("blood_engine"));}
