  function resolveBarrierCollision(enemy){const radius=enemyRadius(enemy),surfaceY=barrierSurfaceY(enemy.x);if(!state.globalBarrierActive||state.globalBarrierHp<=0||enemy.y+radius<surfaceY||enemy.y-radius>surfaceY+16)return false;const integrity=enemy.hp+enemy.shield,defensePower=state.shield+state.globalBarrierHp,exchange=Math.min(integrity,defensePower);damageCore(integrity,"撞击伤害",enemy.x);let remaining=exchange,shieldHit=Math.min(enemy.shield,remaining);enemy.shield-=shieldHit;remaining-=shieldHit;const hpHit=Math.min(enemy.hp,remaining);enemy.hp-=remaining;recordStat("damage","全域屏障",shieldHit+hpHit);enemy.hit=.12;if(enemy.hp<=0)killEnemy(enemy,"全域屏障");state.particles.push({type:"burst",x:enemy.x,y:surfaceY,r:8,maxR:68,life:.38,maxLife:.38,color:state.shield>0?COLORS.gold:COLORS.cyan});spawnSparks(enemy.x,surfaceY,COLORS.cyan,12,135);return true;}
  function attackMiniIfReady(enemy,mini,dt){enemy.attackTimer-=dt;if(enemy.attackTimer>0)return;enemy.attackTimer=enemy.type.ranged?1.55:1.05;damageMiniTurret(mini,Math.max(3,enemy.type.damage*.8));state.beams.push({x1:enemy.x,y1:enemy.y,x2:mini.x,y2:mini.y,color:COLORS.danger,life:.14,maxLife:.14,style:enemy.type.ranged?"laser":"lightning"});}
