  function drawBackground(time){const gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,"#071522");gradient.addColorStop(.58,"#050d16");gradient.addColorStop(1,"#081019");ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);ctx.strokeStyle="rgba(92,230,255,.055)";ctx.lineWidth=1;for(let x=40;x<W;x+=80){ctx.beginPath();ctx.moveTo(x,155);ctx.lineTo(x,CORE_Y+40);ctx.stroke();}const scroll=(time*.02)%70;for(let y=170-scroll;y<CORE_Y;y+=70){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}ctx.strokeStyle="rgba(255,94,120,.18)";ctx.setLineDash([10,10]);ctx.beginPath();ctx.moveTo(0,CORE_Y);ctx.lineTo(W,CORE_Y);ctx.stroke();ctx.setLineDash([]);}
