    ctx.strokeStyle="rgba(92,230,255,.38)";ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,CORE_Y+3);ctx.lineTo(W,CORE_Y+3);ctx.stroke();
    ctx.save();ctx.translate(360,1160);const warning=state.coreHp/state.coreMax<.3,color=warning?COLORS.danger:COLORS.cyan,pulse=.72+Math.sin(state.elapsed*2.4)*.12;
    ctx.shadowColor=color;ctx.shadowBlur=16;ctx.strokeStyle=color;ctx.globalAlpha=.24;ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(0,0,58+i*8,-1.1+i*.2,1.05+i*.2);ctx.stroke();ctx.beginPath();ctx.arc(0,0,58+i*8,2.05+i*.2,4.2+i*.2);ctx.stroke();}
