    ctx.fillStyle=turret.color;for(let i=0;i<4;i++){const angle=Math.PI/4+i*Math.PI/2;ctx.beginPath();ctx.arc(Math.cos(angle)*(radius-4),Math.sin(angle)*(radius-4),2,0,TAU);ctx.fill();}
