      ctx.fillRect(-5,-43,10,32);ctx.strokeRect(-5,-43,10,32);ctx.fillStyle=color;tracePolygon(4,8,Math.PI/4);ctx.fill();
      ctx.fillStyle="#08131d";ctx.strokeStyle=color;ctx.fillRect(-18,-17,8,20);ctx.strokeRect(-18,-17,8,20);ctx.fillRect(10,-17,8,20);ctx.strokeRect(10,-17,8,20);
      ctx.shadowColor=color;ctx.shadowBlur=12;ctx.fillStyle="#fff";ctx.fillRect(-2,-48,4,8);ctx.shadowBlur=0;
