      for(const x of [-14,-8,8,14]){ctx.fillStyle="#07131c";ctx.beginPath();ctx.arc(x,-22,3.4,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,-22,1.3,0,TAU);ctx.fill();}
      ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-19,-34);ctx.lineTo(-3,-34);ctx.lineTo(-11,-43);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(3,-34);ctx.lineTo(19,-34);ctx.lineTo(11,-43);ctx.closePath();ctx.fill();
