      ctx.fillStyle="#11232e";ctx.fillRect(-18,-11,7,26);ctx.strokeRect(-18,-11,7,26);ctx.fillRect(11,-11,7,26);ctx.strokeRect(11,-11,7,26);
      ctx.beginPath();ctx.moveTo(-14,-13);ctx.lineTo(-8,-27);ctx.lineTo(0,-18);ctx.lineTo(8,-31);ctx.lineTo(14,-14);ctx.stroke();ctx.shadowColor=color;ctx.shadowBlur=11;ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(0,0,4,0,TAU);ctx.fill();ctx.shadowBlur=0;
