      ctx.shadowColor=color;ctx.shadowBlur=13;ctx.fillStyle="#eafff8";ctx.fillRect(-4,-22,8,28);ctx.fillRect(-14,-12,28,8);ctx.shadowBlur=0;
      ctx.strokeStyle="rgba(225,255,247,.7)";ctx.beginPath();ctx.arc(0,0,11,0,TAU);ctx.stroke();
